sys_script_include.script:
var CasePoint_AIServices = Class.create();
CasePoint_AIServices.prototype = {
    initialize: function() {},

    processCaseWithOpenAI: function(caseGR) { 
        try {
            var text = caseGR.description.toString();

            // --- FIX: Use GlideRecord for Scoped App Compatibility ---
            // Old: var attachments = new GlideAttachment().getAttachments(...) 
            var att = new GlideRecord('sys_attachment');
            att.addQuery('table_name', caseGR.getTableName());
            att.addQuery('table_sys_id', caseGR.getUniqueValue());
            att.query();

            while (att.next()) {
                var fileName = att.getValue('file_name');
                if (fileName.endsWith('.txt') || fileName.endsWith('.pdf')) {
                    text += '\n\nAttachment: ' + fileName;
                    // Note: Real text extraction requires IntegrationHub or separate plugin
                }
            }
            // ---------------------------------------------------------

            var systemPrompt = "You are a legal case triage AI. Analyze this case and respond in JSON format with:\n" +
                               "- summary: 2-3 sentence summary\n" +
                               "- category: one of [IP, HR, Contract, Compliance]\n" +
                               "- priority: one of [Low, Medium, High, Urgent]\n" +
                               "- confidence: decimal 0.0-1.0";

            var userPrompt = "Case details: " + text;

            var request = new sn_ws.RESTMessageV2();
            request.setEndpoint('https://api.openai.com/v1/chat/completions');
            request.setHttpMethod('POST');
            request.setRequestHeader('Content-Type', 'application/json');
            // Ensure you have the 'openai.api.key' System Property set!
            request.setRequestHeader('Authorization', 'Bearer ' + gs.getProperty('x_1603911_casepo_0.openai.api.key'));

            var body = {
                model: 'gpt-3.5-turbo',
                messages: [
                    { role: 'system', content: systemPrompt },
                    { role: 'user', content: userPrompt }
                ],
                temperature: 0.7, 
                max_tokens: 500
            };
            request.setRequestBody(JSON.stringify(body));

            var response = request.execute();
            var responseBody = response.getBody();

            if (response.getStatusCode() != 200) {
                 throw new Error("OpenAI API Error " + response.getStatusCode() + ": " + responseBody);
            }
            var json = JSON.parse(responseBody);
            var aiText = json.choices[0].message.content;
            var aiJSON = JSON.parse(aiText.replace(/```json|```/g, '').trim());

            // Update case
            caseGR.case_summary = aiJSON.summary || 'No summary generated';
            caseGR.ai_category = aiJSON.category || 'Compliance';
            caseGR.ai_priority = aiJSON.priority || 'Medium';
            caseGR.ai_confidence = aiJSON.confidence || 0.8;
            caseGR.update();

            // Optional: Log to ai_job_log if it exists
            // var log = new GlideRecord('x_1603911_casepo_0_ai_job_log'); 
            // ... log insertion logic ...

            return { success: true, data: aiJSON };

        } catch (e) {
            gs.error('CasePoint AI Error: ' + e.message);
            return { success: false, error: e.message };
        }
    },

    type: 'CasePoint_AIServices'
};
